int
cifs_tree_connect(unsigned int xid, struct cifs_ses *ses, const char *tree,
                  struct cifs_tcon *tcon, const struct nls_table *cp)
{
        int rc;
        char *utf16_path = NULL;
        int utf16_path_len = 0;
        struct smb2_tree_connect_req *req;
        struct smb2_tree_connect_rsp *rsp;

        if (!ses || !tree || !tcon || !cp)
                return -EINVAL;

        utf16_path_len = cp->uni_len(tree);
        if (utf16_path_len < 0) {
                cifs_dbg(VFS, "Failed to determine UTF-16 length of tree name\n");
                return -EINVAL;
        }

        utf16_path = kmalloc(utf16_path_len, GFP_KERNEL);
        if (!utf16_path)
                return -ENOMEM;

        rc = cp->char_set(tree, utf16_path, utf16_path_len);
        if (rc < 0) {
                cifs_dbg(VFS, "Failed to convert tree name to UTF-16\n");
                goto out;
        }

        req = smb2_plain_req_init(SMB2_TREE_CONNECT, ses, 0, &xid);
        if (!req) {
                rc = -ENOMEM;
                goto out;
        }

        req->path_offset = cpu_to_le16(offsetof(struct smb2_tree_connect_req, name));
        req->path_length = cpu_to_le16(utf16_path_len);
        memcpy(req->name, utf16_path, utf16_path_len);

        rc = cifs_call_async(ses, tcon, req, cifs_tree_connect_callback, NULL, 0);
        if (rc < 0) {
                cifs_dbg(VFS, "Tree connect failed with error: %d\n", rc);
                goto out;
        }

        rsp = (struct smb2_tree_connect_rsp *)req->resp_buf;

        tcon->share_type = le32_to_cpu(rsp->share_type);
        tcon->capabilities = le32_to_cpu(rsp->capabilities);

        rc = 0;

out:
        kfree(utf16_path);
        return rc;
}

int cifs_tree_connect(unsigned int xid, struct cifs_ses *ses, const char *tree,
                      struct cifs_tcon *tcon, const struct nls_table *cp)
{
    int rc = 0;
    char *utf16_path = NULL;
    int utf16_path_len;
    struct smb2_tree_connect_req *req;
    struct smb2_tree_connect_rsp *rsp;

    if (!ses || !tcon || !tree) {
        rc = -EINVAL;
        goto out;
    }

    utf16_path_len = strlen(tree) * sizeof(__le16);
    utf16_path = kmalloc(utf16_path_len, GFP_KERNEL);
    if (!utf16_path) {
        rc = -ENOMEM;
        goto out;
    }

    rc = cifsConvertToUTF16(utf16_path, tree, utf16_path_len, cp,
                            nls_codepage, 0);
    if (rc < 0)
        goto out;

    req = cifs_buf_get();
    if (!req) {
        rc = -ENOMEM;
        goto out;
    }

    rsp = cifs_buf_get();
    if (!rsp) {
        rc = -ENOMEM;
        goto out_free_req;
    }

    /* Initialize and send the tree connect request */
    SMB2_TREE_CONNECT_init(xid, ses, tcon, utf16_path, req);

    rc = cifs_call_server(ses->server, req, rsp);
    if (rc < 0)
        goto out_free_rsp;

    /* Parse the response and update tcon */
    tcon->share_type = be32_to_cpu(rsp->ShareType);
    tcon->capabilities = be32_to_cpu(rsp->Capabilities);
    tcon->maximal_access = be32_to_cpu(rsp->MaximalAccess);

    out_free_rsp:
    cifs_buf_release(rsp);
    out_free_req:
    cifs_buf_release(req);
    out:
    kfree(utf16_path);
    return rc;
}

int
smb2_tree_connect(unsigned int xid, struct cifs_ses *ses, const char *tree,
                  struct cifs_tcon *tcon, const struct nls_table *cp)
{
        int rc;
        struct smb2_tree_connect_req *req;
        struct smb2_tree_connect_rsp *rsp = NULL;
        wchar_t *utf16_tree = NULL;
        unsigned int utf16_len;

        if (!ses || !tree || !tcon)
                return -EINVAL;

        utf16_len = utf8s_to_utf16s(tree, strlen(tree), UTF16_HOST_ENDIAN,
                                     NULL, 0);
        utf16_tree = kmalloc(utf16_len * sizeof(wchar_t), GFP_KERNEL);
        if (!utf16_tree)
                return -ENOMEM;

        rc = utf8s_to_utf16s(tree, strlen(tree), UTF16_HOST_ENDIAN,
                             utf16_tree, utf16_len);
        if (rc < 0)
                goto out;

        req = cifs_smb2_init(SMB2_TREE_CONNECT, NULL, 0, NULL);
        if (!req) {
                rc = -ENOMEM;
                goto out;
        }

        req->PathOffset = cpu_to_le16(offsetof(struct smb2_tree_connect_req, Buffer));
        req->PathLength = cpu_to_le16(utf16_len * sizeof(wchar_t));
        memcpy(req->Buffer, utf16_tree, utf16_len * sizeof(wchar_t));

        rc = cifs_call_async(ses, tcon, (char *)req, smb2_tree_connect_callback,
                             NULL, NULL, 0, CIFS_ASYNC_OP);
        if (rc)
                goto out;

        rsp = (struct smb2_tree_connect_rsp *)req->iov[0].iov_base;

        tcon->share_type = rsp->ShareType;
        tcon->capabilities = le32_to_cpu(rsp->Capabilities);
        tcon->maximal_access = le32_to_cpu(rsp->MaximalAccess);

out:
        if (utf16_tree)
                kfree(utf16_tree);
        if (req)
                cifs_buf_release(req);

        return rc;
}

int cifs_tree_connect(unsigned int xid, struct cifs_ses *ses, const char *tree,
                      struct cifs_tcon *tcon, const struct nls_table *cp) {
    int rc = 0;
    struct smb2_tree_connect_request *request = NULL;
    struct smb2_tree_connect_response *response = NULL;
    char *utf16_path = NULL;
    size_t utf16_path_len;

    if (!ses || !tree || !tcon || !cp)
        return -EINVAL;

    rc = smb2_allocate_tree_connect_buffers(&request, &response);
    if (rc) {
        cifs_dbg(VFS, "Failed to allocate memory for SMB2 tree connect buffers\n");
        return rc;
    }

    request->path_offset = sizeof(struct smb2_tree_connect_request);
    rc = cifs_strndup_from_unix(tree, strlen(tree), &utf16_path, &utf16_path_len, cp);
    if (rc) {
        cifs_dbg(VFS, "Failed to convert tree name to UTF-16\n");
        goto out;
    }

    request->path_length = utf16_path_len;
    memcpy(request + 1, utf16_path, utf16_path_len);

    rc = SMB2_ioctl(xid, ses->server, ses->suid, NULL, NULL, 0, 0, NULL);
    if (rc) {
        cifs_dbg(VFS, "SMB2 tree connect request failed: %d\n", rc);
        goto out;
    }

    tcon->share_type = response->share_type;
    tcon->capabilities = response->capabilities;
    tcon->maximal_access = response->maximal_access;

out:
    kfree(utf16_path);
    kfree(request);
    kfree(response);

    if (rc) {
        tcon->flags |= TCAL_ATTRIBS;
        tcon->flags |= TCAL_RECONNECT;
        tcon->Flags2 |= CIFS_NEGFLG2_UNICODE;
    }

    return rc;
}

int cifs_tree_connect(unsigned int xid, struct cifs_ses *ses, const char *tree, struct cifs_tcon *tcon, const struct nls_table *cp) {
    int rc = 0;
    char *utf16_tree = NULL;
    int utf16_len = 0;

    if (!ses || !tree || !tcon || !cp)
        return -EINVAL;

    utf16_len = strlen(tree) * sizeof(__u16) + sizeof(__u16);
    utf16_tree = kmalloc(utf16_len, GFP_KERNEL);
    if (!utf16_tree)
        return -ENOMEM;

    rc = cifs_strndup_to_utf16(tree, strlen(tree), (wchar_t **)&utf16_tree, cp, true);
    if (rc < 0)
        goto free_out;

    rc = SMB2_tcon(xid, ses, utf16_tree, tcon);
    if (rc < 0)
        goto free_out;

    tcon->tid = tcon->tid;
    tcon->ses = ses;
    tcon->flags |= TC_GLOBAL_CAPS;

free_out:
    kfree(utf16_tree);
    return rc;
}
